    it.skipIf(!('Activity' in React))(
      'does not complete the superseded phase when in flips on reconnect',
      () => {
        const handlers = {
          onEnter: spy(),
          onEntering: spy(),
          onEntered: spy(),
          onExit: spy(),
          onExiting: spy(),
          onExited: spy(),
        };

        function ActivityHarness(props: { in: boolean; mode: 'hidden' | 'visible' }) {
          return (
            <React.Activity mode={props.mode}>
